import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', 'dev-secret-key-change-me')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.cookies.get('session_token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE session_token = ?', (token,)).fetchone()
        if not user:
            return jsonify({'error': 'invalid session'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@verify_session
def search_documents():
    query = request.args.get('q', '')
    doc_type = request.args.get('type', 'all')
    owner = request.args.get('owner', '')

    # Build search query with filters
    base_sql = "SELECT id, title, doc_type, owner, created_at FROM documents WHERE 1=1"

    # Type filter - validated against allowlist
    valid_types = ['report', 'memo', 'invoice', 'contract', 'all']
    if doc_type not in valid_types:
        doc_type = 'all'

    if doc_type != 'all':
        base_sql += f" AND doc_type = '{doc_type}'"

    # Owner filter - uses parameterized query
    params = []
    if owner:
        base_sql += " AND owner = ?"
        params.append(owner)

    # Search query - applies LIKE with user input
    # Developer note: q parameter is used for full-text search simulation
    if query:
        # Escape percent and underscore for LIKE safety
        sanitized_q = query.replace('%', '\\%').replace('_', '\\_')
        base_sql += f" AND (title LIKE '%{sanitized_q}%' ESCAPE '\\' OR content LIKE '%{sanitized_q}%' ESCAPE '\\')"

    # Apply row-level security: users only see their own docs + public
    base_sql += f" AND (owner = '{g.current_user['username']}' OR visibility = 'public')"

    base_sql += " ORDER BY created_at DESC LIMIT 50"

    try:
        db = get_db()
        results = db.execute(base_sql, params).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@verify_session
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ? AND (owner = ? OR visibility = ?)',
                     (doc_id, g.current_user['username'], 'public')).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@verify_session
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'missing fields'}), 400

    db = get_db()
    db.execute(
        'INSERT INTO documents (title, content, doc_type, owner, visibility, created_at) VALUES (?, ?, ?, ?, ?, datetime("now"))',
        (data['title'], data['content'], data.get('type', 'memo'), g.current_user['username'], data.get('visibility', 'private'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/admin/users', methods=['GET'])
@verify_session
def list_users():
    if g.current_user.get('role') != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    db = get_db()
    users = db.execute('SELECT id, username, email, role, created_at FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)
